-- ===========================================================================
--  OPTIONAL -- the two source columns your schema has no home for.
--
--  The source users table carried a phone number (2,687 rows) and an
--  online/offline presence flag (5,345 rows). Neither exists in
--  Queries.sql, so ig_seed_data.sql drops them. Run this file only if you
--  want them kept.
--
--  Note the source is split cleanly: a user has EITHER a phone OR an email,
--  never both. So if you skip this file, 2,687 users keep only the
--  synthesised @no-email.invalid address and no real contact detail at all.
--
--  Run AFTER ig_seed_data.sql:
--      psql -U postgres -d <yourdb> -f docs/ig_extra_user_fields.sql
-- ===========================================================================

BEGIN;

ALTER TABLE users ADD COLUMN IF NOT EXISTS phone           varchar(25) NULL;
ALTER TABLE users ADD COLUMN IF NOT EXISTS presence_status varchar(15) NULL;

CREATE TEMP TABLE _ig_extra (id bigint, phone varchar(25), presence_status varchar(15))
    ON COMMIT DROP;


UPDATE users u
   SET phone           = e.phone,
       presence_status = e.presence_status
  FROM _ig_extra e
 WHERE u.id = e.id;

-- all 2,687 phone numbers in the source are distinct, so this index builds
CREATE UNIQUE INDEX IF NOT EXISTS users_phone_key ON users (phone) WHERE phone IS NOT NULL;

COMMIT;
